    if i % 15 == 0:
        print("FizzBuzz")
    elif i % 3 == 0:
        print("Fizz")
    elif i % 5 == 0:
        print("Buzz")
    else:
        print(i)

shapes.code:
from dataclasses import dataclass


@dataclass
class Rectangle:
    width: int
    height: int

    def area(self) -> int:
        return self.width * self.height


@dataclass
class Triangle:
    base: int
    height: int

    def area(self) -> int:
        return self.base * self.height // 2


for shape in (Rectangle(3, 4), Triangle(10, 3)):
    print(f"{type(shape).__name__}: {shape.area()}")
